/// Shaders.cpp's assembleOrgan: the version line, kFilament, then kOrgan, then
/// the body. The status lamp is the version line and its body alone.
const assembleOrgan = (version, filament, body) => version + filament + ORGAN + body;

//---------------------------------------------------------------------------
// What the organ hears. The page's Audio menu (plugin.js's AUDIO, in the host
// row under the picture) stands in for the plugin's Audio Input and Rescan
// Inputs: it chooses one of fitest's sources, glue.cpp's fo_source -- 0
// nothing at all (the plugin's None), 1 the synthetic track, 2 zeros
// (--silent), 3 a file the visitor chose, decoded by the page (--wav).
//---------------------------------------------------------------------------

/// organ::Lamp, and what each says (Organ.h).
export const LAMP = { Idle: 0, Green: 1, Red: 2, RedBlink: 3 };
export const LAMP_WORDS = [
  'amber: nothing to listen to',
  'green: an input is delivering',
  'steady red: open and bit-exactly silent',
  'blinking red: missing or refused',
];
/// earshot::CaptureState, in its order.
export const CAPTURE_STATES = ['Closed', 'Opening', 'Running', 'Silent', 'Missing', 'Failed'];

//---------------------------------------------------------------------------
// The CPU half: one organ::Organ in the WebAssembly, and its feeder.
//---------------------------------------------------------------------------

/**
 * `frame()` is ProcessOpenGL's organ block -- `organ->Activate()`, then
 * `organ->Advance( start, now, hertz, firstHalf, halves, settings )` -- with
 * fitest's feedOrgan before it; `off()` is feedOrgan with the Organ Off and
 * then ProcessOpenGL's `organ->Deactivate()`.
 *
 * **A new organ, from the music's start**, when the Audio choice changes or a
 * new file is chosen: a fresh `organ::Organ`, as a new plugin instance
 * constructs one, and a fresh feeder, as a new fitest run starts one (the
 * plugin's nearest act is choosing another Audio Input, which restarts its
 * stream). The wall's temperatures and the organ's ramps are the plugin's GPU
 * state and carry on.
 *
 * **The page's clock going backwards** (Restart) is the organ's own business:
 * Organ::Advance sees a frame that does not start where the stream had got to
 * and lays the stream onto the clock again from there. The feeder, which
 * fitest never runs backwards, is re-anchored the way fitest re-anchors it
 * after the Organ was Off (`off()`): the music carries on where it stopped,
 * as a device's would.
 */
class OrganCpu {
  constructor(module) {
    this.m = module;
    this.instance = 0;
    this.key = null;
    this.choice = { key: 'none', source: 0, file: null };
    this.lastNow = null;
    this.made = 0;
    this.rowCount = 0;
  }

  /**
   * What to feed from the next organ frame on: `{ key, source, file }`, the
   * key naming the choice (a new key, a new organ), the source glue.cpp's
   * fo_source, the file `{ samples, frames, rate, channels }` for source 3.
   */
  feed(choice) {
    this.choice = choice;
  }

  /** A new plugin instance (hooks.fresh): a new organ on the next organ frame. */
  reset() {
    if (this.instance) this.m._fo_delete(this.instance);
    this.instance = 0;
    this.key = null;
    this.lastNow = null;
  }

  make(choice) {
    const m = this.m;
    if (this.instance) m._fo_delete(this.instance);
    this.instance = m._fo_new();
    m._fo_source(this.instance, choice.source);
    if (choice.source === 3) {
      const f = choice.file;
      const at = m._malloc(f.samples.length * 4);
      m.HEAPF32.set(f.samples, at >> 2);
      m._fo_wav(this.instance, at, f.frames, f.rate, f.channels);
      m._free(at);
    }
    this.made += 1;
  }

  /** fitest's feedOrgan with the Organ Off, then organ->Deactivate(). */
  off() {
    if (!this.instance) return;
    this.m._fo_feed_off(this.instance);
    this.m._fo_deactivate(this.instance);
  }

  /**
   * One organ frame of host time [start, now). `values` are the host's floats
   * for Crossover Low, Crossover High and the three gains, which the glue turns
   * into Settings through Organ.cpp's own laws. Returns the row count.
   */
  frame({ start, now, hertz, firstHalf, halves, values }) {
    const m = this.m;
    const { choice } = this;
    if (!this.instance || choice.key !== this.key) {
      this.make(choice);
      this.key = choice.key;
    } else if (this.lastNow !== null && now < this.lastNow) {
      m._fo_feed_off(this.instance);
    }
    this.lastNow = now;
    m._fo_feed_frame(this.instance, start, now);
    m._fo_activate(this.instance);
    m._fo_advance(this.instance, start, now, hertz, firstHalf, halves,
      values.low, values.high, values.bass, values.mid, values.treble);
    this.rowCount = m._fo_row_count(this.instance);
    return this.rowCount;
  }

  /** The last Advance's rows, a view into the module's memory (valid until the next call). */
  rows() {
    return new Float32Array(this.m.HEAPF32.buffer, this.m._fo_rows(this.instance), this.rowCount * ROW_POINTS * 4);
  }

  firstHalf() {
    return this.instance ? this.m._fo_first_half(this.instance) : 0;
  }

  lamp() {
    return this.instance ? this.m._fo_lamp(this.instance) : LAMP.Idle;
  }

  /** Seconds fed, FIFO underruns and drops (samples), the tap's rate, earshot's state, Active. */
  stats() {
    if (!this.instance) return null;
    const at = this.m._fo_stats(this.instance) >> 3;
    const h = this.m.HEAPF64;
    return {
      fed: h[at], underruns: h[at + 1], dropped: h[at + 2], tapRate: h[at + 3],
      state: h[at + 4] >= 0 ? CAPTURE_STATES[h[at + 4]] ?? String(h[at + 4]) : 'no engine yet',
      active: h[at + 5] !== 0,
    };
  }

  /** Organ::Calls(), process-wide: Engines built, device lists made, selectDevice calls. */
  counters() {
    if (!this.instance) return null;
    const at = this.m._fo_counters(this.instance) >> 2;
    const h = this.m.HEAP32;
    return { engines: h[at], lists: h[at + 1], selects: h[at + 2] };
  }
}

//---------------------------------------------------------------------------
// The GL half: Filament::ensureOrgan, the control upload and drawStatusLamp.
//---------------------------------------------------------------------------

const f32 = Math.fround;

/// Organ.h's grid, from plugin.js's generated block (createOrgan's `constants`).
let ROW_POINTS = 0;
let MAX_ROWS = 0;
let INTERVALS = 0;

class OrganGL {
  /** Filament::ensureOrgan: the two programs, the gel table, the control texture. */
  constructor(gl, quad, { version, filament, vertex }) {
    this.gl = gl;
    this.quad = quad;
    this.organShader = new Program(gl, vertex, assembleOrgan(version, filament, ORGAN_THERMAL_BODY), 'organ thermal');
    this.lampShader = new Program(gl, vertex, version + STATUS_LAMP_BODY, 'status lamp');

    const texture = (width, height, data) => {
      const t = gl.createTexture();
      gl.bindTexture(gl.TEXTURE_2D, t);
      gl.texStorage2D(gl.TEXTURE_2D, 1, gl.RGBA32F, width, height);
      gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
      gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
      gl.texSubImage2D(gl.TEXTURE_2D, 0, 0, 0, width, height, gl.RGBA, gl.FLOAT, data);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      gl.bindTexture(gl.TEXTURE_2D, null);
      return t;
    };
    // The gel table: a row of the Planck grid per gel, read with texelFetch.
    this.gelTexture = texture(GEL_ROW_COUNT, GEL_COUNT, new Float32Array(GEL_TABLE));
    // The control integral: a row per half-cycle, refilled every frame.
    this.controlTexture = texture(ROW_POINTS, MAX_ROWS, new Float32Array(ROW_POINTS * MAX_ROWS * 4));

    // The thermal pass writes three RGBA32F targets at once (the temperatures,
    // the light and the ramps). The plugin assumes a GL 4.1 driver will; a
    // browser that will not is told so here, and the organ stays off, rather
    // than the pass being split into something the plugin does not do.
    const probe = [0, 1, 2].map(() => texture(1, 1, new Float32Array(4)));
    const fbo = gl.createFramebuffer();
    gl.bindFramebuffer(gl.FRAMEBUFFER, fbo);
    probe.forEach((t, i) => gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0 + i, gl.TEXTURE_2D, t, 0));
    gl.drawBuffers([gl.COLOR_ATTACHMENT0, gl.COLOR_ATTACHMENT1, gl.COLOR_ATTACHMENT2]);
    const status = gl.checkFramebufferStatus(gl.FRAMEBUFFER);
    gl.drawBuffers([gl.COLOR_ATTACHMENT0]);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    gl.deleteFramebuffer(fbo);
    probe.forEach((t) => gl.deleteTexture(t));
    if (status !== gl.FRAMEBUFFER_COMPLETE) {
      throw new GLError(`this browser will not render the organ's three RGBA32F targets at once (framebuffer status 0x${status.toString(16)})`);
    }
  }

  /** ProcessOpenGL's glTexSubImage2D of the rows. */
  upload(rows, count) {
    const gl = this.gl;
    gl.bindTexture(gl.TEXTURE_2D, this.controlTexture);
    gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
    gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
    gl.texSubImage2D(gl.TEXTURE_2D, 0, 0, 0, ROW_POINTS, count, gl.RGBA, gl.FLOAT, rows);
    gl.bindTexture(gl.TEXTURE_2D, null);
  }

  /**
   * Filament::drawStatusLamp over WebGL2, into the canvas (the host's FBO),
   * after the wall: a disc in the top-right corner, its colour the organ's
   * Lamp, blinking red at 1 Hz on the host's clock. In float, as the C++.
   */
  drawStatusLamp(state, viewport, now) {
    const gl = this.gl;
    let colour = [1.0, 0.62, 0.05]; // amber: nothing to listen to
    switch (state) {
      case LAMP.Green: colour = [0.15, 1.0, 0.25]; break;
      case LAMP.Red: colour = [1.0, 0.05, 0.02]; break;
      case LAMP.RedBlink: colour = [now - Math.floor(now) < 0.5 ? 1.0 : 0.15, 0.03, 0.02]; break;
      default: break;
    }
    // Top right, a little in from the corner.
    const radius = Math.max(3.0, f32(f32(0.014) * viewport[3]));
    const cx = f32(f32(viewport[0] + viewport[2]) - f32(f32(2.2) * radius));
    const cy = f32(f32(viewport[1] + viewport[3]) - f32(f32(2.2) * radius));
    const reach = Math.ceil(radius) + 3;
    const scissorWas = gl.isEnabled(gl.SCISSOR_TEST);
    const blendWas = gl.isEnabled(gl.BLEND);
    const box = gl.getParameter(gl.SCISSOR_BOX);
    gl.enable(gl.SCISSOR_TEST);
    gl.scissor(Math.trunc(cx) - reach, Math.trunc(cy) - reach, 2 * reach, 2 * reach);
    gl.enable(gl.BLEND);
    gl.blendFuncSeparate(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA, gl.ZERO, gl.ONE);
    const s = this.lampShader.use();
    s.set('LampColour', colour[0], colour[1], colour[2]);
    s.set('LampCentre', cx, cy);
    s.set('LampRadius', radius);
    this.quad.draw();
    gl.blendFunc(gl.ONE, gl.ZERO);
    if (!blendWas) gl.disable(gl.BLEND);
    gl.scissor(box[0], box[1], box[2], box[3]);
    if (!scissorWas) gl.disable(gl.SCISSOR_TEST);
    return { colour, radius, cx, cy };
  }
}

/** The organ's firing point for a white cell (b = 1): fitest's firstCrossing, ported. */
export function firstCrossing(rows, row, channel, theta) {
  const at = (j) => rows[(row * ROW_POINTS + j) * 4 + channel];
  let a = at(0);
  if (a >= theta) return 0.0;
  for (let j = 0; j < INTERVALS; j += 1) {
    const b = at(j + 1);
    if (b >= theta) {
      const span = b - a;
      const t = span > 0.0 ? Math.min(Math.max((theta - a) / span, 0.0), 1.0) : 0.0;
      return (j + t) / INTERVALS;
    }
    a = b;
  }
  return 2.0;
}

/**
 * The organ, built: fetch and instantiate the module, set FILAMENT_NO_DEVICES,
 * and compile the passes. Throws (and the plugin's organ stays off) if any of
 * it fails.
 */
export async function createOrgan(gl, quad, sources, { load } = {}) {
  ({ rowPoints: ROW_POINTS, maxRows: MAX_ROWS, intervals: INTERVALS } = sources.constants);
  const make = load ?? (async () => (await import('./filament-organ.js')).default());
  const module = await make();
  module._fo_prepare();
  const glSide = new OrganGL(gl, quad, sources);
  return { gl: glSide, cpu: new OrganCpu(module), module, lampWords: LAMP_WORDS };
}
